//! CLDR currency data (symbols, display names, fraction digits).
//!
//! The table is generated by tools/unicode/format/generate_misc.py from the
//! CLDR locale currency blocks and supplemental fraction digits.

const std = @import("std");
const plural = @import("plurals.zig");
const likely_subtags = @import("likely_subtags.zig");
const region_data = @import("currency_regions.zig");

const blob = @embedFile("currencies_data.bin");

const header_len = 24;
const locale_count = readU16(8);
const currency_count = readU16(10);
const entry_count = readU32(12);
const string_length = readU32(16);

const code_offset = header_len;
const locale_offset = code_offset + @as(usize, currency_count) * 8;
const entry_offset = locale_offset + @as(usize, locale_count) * 12;
const strings_offset = entry_offset + @as(usize, entry_count) * 32;

comptime {
    if (blob.len < header_len or !std.mem.eql(u8, blob[0..4], "CJGD") or
        blob[4] != 2)
    {
        @compileError("invalid currency data");
    }
    if (strings_offset + @as(usize, string_length) != blob.len) {
        @compileError("invalid currency data lengths");
    }
}

pub const Entry = struct {
    symbol: []const u8,
    names: [6][]const u8,
};

fn readU16(offset: usize) u16 {
    return std.mem.readInt(u16, blob[offset..][0..2], .little);
}

fn readU32(offset: usize) u32 {
    return std.mem.readInt(u32, blob[offset..][0..4], .little);
}

fn strAt(offset: u32) []const u8 {
    if (offset == 0) return "";
    return std.mem.sliceTo(blob[strings_offset + @as(usize, offset) ..], 0);
}

fn codeAt(index: usize) []const u8 {
    return strAt(readU32(code_offset + index * 8));
}

/// Number of CLDR currency codes in the table.
pub fn count() usize {
    return currency_count;
}

/// Currency code at `index` in sorted order (for enumeration surfaces).
pub fn codeAtPublic(index: usize) []const u8 {
    return codeAt(index);
}

fn codeIndex(code: []const u8) ?usize {
    var low: usize = 0;
    var high: usize = currency_count;
    while (low < high) {
        const middle = low + (high - low) / 2;
        switch (std.mem.order(u8, codeAt(middle), code)) {
            .lt => low = middle + 1,
            .gt => high = middle,
            .eq => return middle,
        }
    }
    return null;
}

/// CLDR fraction digits for a currency code (defaults to 2).
pub fn fractionDigits(code: []const u8) u8 {
    const index = codeIndex(code) orelse return 2;
    return blob[code_offset + index * 8 + 4];
}

/// CLDR cash fraction digits for a currency code (defaults to the regular
/// fraction digits).
pub fn cashFractionDigits(code: []const u8) u8 {
    const index = codeIndex(code) orelse return 2;
    return blob[code_offset + index * 8 + 5];
}

/// CLDR cash rounding increment for a currency code, in the smallest cash
/// fraction unit (for example 5 for CHF, 50 for DKK; 0 means no increment).
pub fn cashRounding(code: []const u8) u8 {
    const index = codeIndex(code) orelse return 0;
    return blob[code_offset + index * 8 + 6];
}

fn localeId(index: usize) []const u8 {
    const base = locale_offset + index * 12;
    const id_offset = readU32(base);
    const id_length = blob[base + 4];
    return blob[strings_offset + @as(usize, id_offset) ..][0..id_length];
}

fn findLocaleRecord(locale_name: []const u8) ?usize {
    var low: usize = 0;
    var high: usize = locale_count;
    while (low < high) {
        const middle = low + (high - low) / 2;
        switch (std.mem.order(u8, localeId(middle), locale_name)) {
            .lt => low = middle + 1,
            .gt => high = middle,
            .eq => return middle,
        }
    }
    return null;
}

fn lookup(locale_name: []const u8, code: []const u8) ?Entry {
    const currency = codeIndex(code) orelse return null;
    var locale_index = findLocaleRecord(locale_name);
    if (locale_index == null) {
        if (std.mem.indexOfAny(u8, locale_name, "-_")) |position| {
            locale_index = findLocaleRecord(locale_name[0..position]);
        }
    }
    const record_index = locale_index orelse
        findLocaleRecord("en") orelse return null;
    const base = locale_offset + record_index * 12;
    var low: usize = readU16(base + 6);
    var high: usize = low + readU16(base + 8);
    while (low < high) {
        const middle = low + (high - low) / 2;
        const entry_base = entry_offset + middle * 32;
        const index = readU16(entry_base);
        if (index < currency) {
            low = middle + 1;
        } else if (index > currency) {
            high = middle;
        } else {
            var names: [6][]const u8 = undefined;
            for (0..6) |name_index| {
                names[name_index] = strAt(readU32(entry_base + 8 + name_index * 4));
            }
            return .{
                .symbol = strAt(readU32(entry_base + 4)),
                .names = names,
            };
        }
    }
    return null;
}

/// True when the locale has a currency record, even if it lacks a particular
/// currency. ICU falls back to the ISO code for such locales instead of
/// borrowing another locale's symbol.
pub fn hasLocale(locale_name: []const u8) bool {
    if (findLocaleRecord(locale_name) != null) return true;
    if (std.mem.indexOfAny(u8, locale_name, "-_")) |position| {
        return findLocaleRecord(locale_name[0..position]) != null;
    }
    return false;
}

const lookup_cache_len = 8;

const LookupCacheEntry = struct {
    locale: [16]u8 = [_]u8{0} ** 16,
    locale_len: u8 = 0,
    code: [8]u8 = [_]u8{0} ** 8,
    code_len: u8 = 0,
    found: bool = false,
    entry: Entry = undefined,
};

/// Currency formatting repeats the same locale and code, so the three
/// binary searches behind `lookup` are cached per thread.
threadlocal var lookup_cache: [lookup_cache_len]LookupCacheEntry =
    [_]LookupCacheEntry{.{}} ** lookup_cache_len;

/// Localized symbol and display names for a currency, or null when the
/// locale has no data for it.
pub fn find(locale_name: []const u8, code: []const u8) ?Entry {
    if (locale_name.len <= 16 and code.len <= 8) {
        var hash: usize = locale_name.len * 31 + code.len;
        for (locale_name) |byte| hash = hash *% 31 +% byte;
        for (code) |byte| hash = hash *% 31 +% byte;
        const slot = &lookup_cache[hash & (lookup_cache_len - 1)];
        if (slot.locale_len == locale_name.len and
            slot.code_len == code.len and
            std.mem.eql(u8, slot.locale[0..slot.locale_len], locale_name) and
            std.mem.eql(u8, slot.code[0..slot.code_len], code))
        {
            return if (slot.found) slot.entry else null;
        }
        const result = lookup(locale_name, code);
        slot.locale_len = @intCast(locale_name.len);
        @memcpy(slot.locale[0..locale_name.len], locale_name);
        slot.code_len = @intCast(code.len);
        @memcpy(slot.code[0..code.len], code);
        slot.found = result != null;
        if (result) |entry| slot.entry = entry;
        return result;
    }
    return lookup(locale_name, code);
}

/// CLDR currency code for an ISO 3166 region, such as "USD" for "US".
pub fn codeForRegion(region: []const u8) ?[]const u8 {
    var low: usize = 0;
    var high = region_data.regions.len;
    while (low < high) {
        const middle = low + (high - low) / 2;
        const entry = region_data.regions[middle];
        switch (std.mem.order(u8, entry.id, region)) {
            .lt => low = middle + 1,
            .gt => high = middle,
            .eq => return entry.code,
        }
    }
    return null;
}

/// CLDR currency code for a locale's region, such as "USD" for "en" and
/// "GBP" for "en-GB".
pub fn codeForLocale(locale_name: []const u8) ?[]const u8 {
    const region = likely_subtags.regionForLocale(locale_name) orelse
        return null;
    return codeForRegion(region);
}

/// Localized currency symbol, falling back to the ISO code when the locale
/// has no symbol for it.
pub fn symbol(locale_name: []const u8, code: []const u8) []const u8 {
    if (find(locale_name, code)) |entry| {
        if (entry.symbol.len != 0) return entry.symbol;
    }
    return code;
}

/// Localized currency display name for a plural category, falling back to
/// the `other` name and then the ISO code.
pub fn name(
    locale_name: []const u8,
    code: []const u8,
    category: plural.Category,
) []const u8 {
    if (find(locale_name, code)) |entry| {
        const value = entry.names[@intFromEnum(category)];
        if (value.len != 0) return value;
        const other = entry.names[@intFromEnum(plural.Category.other)];
        if (other.len != 0) return other;
    }
    return code;
}

test "currency data" {
    const testing = @import("std").testing;
    try testing.expectEqual(@as(u8, 2), fractionDigits("USD"));
    try testing.expectEqual(@as(u8, 0), fractionDigits("JPY"));
    try testing.expectEqual(@as(u8, 3), fractionDigits("BHD"));
    try testing.expectEqual(@as(u8, 2), cashFractionDigits("CHF"));
    try testing.expectEqual(@as(u8, 5), cashRounding("CHF"));
    try testing.expectEqual(@as(u8, 0), cashFractionDigits("NOK"));
    try testing.expectEqual(@as(u8, 0), cashRounding("NOK"));
    try testing.expectEqual(@as(u8, 50), cashRounding("DKK"));
    try testing.expectEqual(@as(u8, 0), cashRounding("USD"));
    const usd = find("en", "USD").?;
    try testing.expectEqualStrings("$", usd.symbol);
    try testing.expectEqualStrings("US dollars", usd.names[5]);
    const afn = find("fr", "AFN");
    try testing.expect(afn != null);
    try testing.expectEqualStrings("", afn.?.symbol);
    try testing.expectEqualStrings("afghanis afghan", afn.?.names[5]);
    try testing.expectEqualStrings("$", symbol("en", "USD"));
    try testing.expectEqualStrings("XYZ", symbol("en", "XYZ"));
    try testing.expectEqualStrings(
        "US dollars",
        name("en", "USD", .other),
    );
    try testing.expectEqualStrings(
        "afghani afghan",
        name("fr", "AFN", .one),
    );
    try testing.expectEqualStrings("USD", codeForRegion("US").?);
    try testing.expectEqualStrings("GBP", codeForRegion("GB").?);
    try testing.expectEqualStrings("CNY", codeForRegion("CN").?);
    try testing.expect(codeForRegion("QQ") == null);
    try testing.expectEqualStrings("USD", codeForLocale("en").?);
    try testing.expectEqualStrings("GBP", codeForLocale("en-GB").?);
    try testing.expectEqualStrings("TWD", codeForLocale("zh-Hant-TW").?);
}
